from operator import le
import rclpy
from rclpy.node import Node
import numpy as np
from bodyctrl_msgs.msg import MotorStatusMsg

class ArmStatusRecorder(Node):
    def __init__(self):
        super().__init__('arm_status_recorder')
        self.subscription = self.create_subscription(
            MotorStatusMsg,
            '/arm/status',
            self.arm_status_callback,
            1000
        )
        self.subscription  # prevent unused variable warning
        self.left_arm_pos = np.array([])
        self.right_arm_pos = np.array([])
        self.left_arm_vel = np.array([])
        self.right_arm_vel = np.array([])
        self.left_arm_current = np.array([])
        self.right_arm_current = np.array([])

    def arm_status_callback(self, msg):
        # 这里可根据需要处理接收到的 MotorStatusMsg 消息
        # self.get_logger().info(f"收到 /arm/status 消息: {msg}")
        dict = {}
        for motor in msg.status:
            # self.get_logger().info(f"电机ID: {motor.name}, 位置: {motor.pos}, 速度: {motor.speed}, 电流: {motor.current}, 温度: {motor.temperature}")
            dict[motor.name] = {
                'pos': motor.pos,
                'speed': motor.speed,
                'current': motor.current,
            }
        left_pos_list = [dict[11]['pos'], dict[12]['pos'], dict[13]['pos'], dict[14]['pos'], dict[15]['pos'], dict[16]['pos'], dict[17]['pos']]
        right_pos_list = [dict[21]['pos'], dict[22]['pos'], dict[23]['pos'], dict[24]['pos'], dict[25]['pos'], dict[26]['pos'], dict[27]['pos']]
        left_vel_list = [dict[11]['speed'], dict[12]['speed'], dict[13]['speed'], dict[14]['speed'], dict[15]['speed'], dict[16]['speed'], dict[17]['speed']]
        right_vel_list = [dict[21]['speed'], dict[22]['speed'], dict[23]['speed'], dict[24]['speed'], dict[25]['speed'], dict[26]['speed'], dict[27]['speed']]
        left_current_list = [dict[11]['current'], dict[12]['current'], dict[13]['current'], dict[14]['current'], dict[15]['current'], dict[16]['current'], dict[17]['current']]
        right_current_list = [dict[21]['current'], dict[22]['current'], dict[23]['current'], dict[24]['current'], dict[25]['current'], dict[26]['current'], dict[27]['current']]
        self.left_arm_pos = np.vstack([self.left_arm_pos, left_pos_list]) if self.left_arm_pos.size else np.array([left_pos_list])
        self.right_arm_pos = np.vstack([self.right_arm_pos, right_pos_list]) if self.right_arm_pos.size else np.array([right_pos_list])
        self.left_arm_vel = np.vstack([self.left_arm_vel, left_vel_list]) if self.left_arm_vel.size else np.array([left_vel_list])
        self.right_arm_vel = np.vstack([self.right_arm_vel, right_vel_list]) if self.right_arm_vel.size else np.array([right_vel_list])
        self.left_arm_current = np.vstack([self.left_arm_current, left_current_list]) if self.left_arm_current.size else np.array([left_current_list])
        self.right_arm_current = np.vstack([self.right_arm_current, right_current_list]) if self.right_arm_current.size else np.array([right_current_list])
        if self.left_arm_pos.shape[0] % 1000 == 0:
            print(f"已记录 {self.left_arm_pos.shape[0]} 条数据")

def main(args=None):
    rclpy.init(args=args)
    node = ArmStatusRecorder()
    try:
        rclpy.spin(node)
    except KeyboardInterrupt:
        pass
    finally:
        # 将最终的关节数据保存到本地 npy 文件
        import os
        if not os.path.exists('npy_data'):
            os.makedirs('npy_data')
        np.save('npy_data/left_arm_pos.npy', node.left_arm_pos)
        np.save('npy_data/right_arm_pos.npy', node.right_arm_pos)
        np.save('npy_data/left_arm_vel.npy', node.left_arm_vel)
        np.save('npy_data/right_arm_vel.npy', node.right_arm_vel)
        np.save('npy_data/left_arm_current.npy', node.left_arm_current)
        np.save('npy_data/right_arm_current.npy', node.right_arm_current)
        node.destroy_node()
        rclpy.shutdown()

if __name__ == '__main__':
    main()
